#!/usr/bin/env bash
# Publishes the files in out/ (SwitchRecomp.exe, SwitchRecomp-linux-x86_64.tar.gz and
# their .sha256 files) as a GitHub release.
#
#   KIND=dev                  replaces the "dev" pre-release with this commit's build;
#                             the notes list the commits since the previous one
#   KIND=stable VERSION=v1.2  release v1.2 with notes generated by GitHub (the tag is
#                             created at this commit if needed). A version with a
#                             suffix like v2.0.0-rc.1 is published as a pre-release.
#
# Needs GH_TOKEN, GH_REPO and GITHUB_SHA. When DISCORD_WEBHOOK is set, versioned
# releases are also announced there.
set -euo pipefail

files=(out/*)
short=${GITHUB_SHA:0:7}
now=$(date -u '+%Y-%m-%d %H:%M UTC')

about() {
    echo "- **SwitchRecomp.exe** (Windows): one file with the app, the recompiler, the runtimes, Python, TCC and GCC."
    echo "- **SwitchRecomp-linux-x86_64.tar.gz** (Linux): one program with the app, the recompiler, the runtimes and TCC."
    echo "  It uses the system's Python 3 and GCC."
}
checksums() {
    echo "SHA-256:"
    echo
    for f in out/*.sha256; do
        read -r hash name < "$f"
        echo "- $name: \`$hash\`"
    done
}

if [ "$KIND" = dev ]; then
    prev=$(gh api "repos/$GH_REPO/git/ref/tags/dev" --jq .object.sha 2>/dev/null || true)
    # on the first run there is no dev tag, and gh prints the error body instead of a SHA
    [[ $prev =~ ^[0-9a-f]{40}$ ]] || prev=""
    {
        echo "Automatic build of \`master\` at $short ($now)."
        echo
        about
        echo
        echo "This build is replaced by every push to master; versioned releases are the stable ones."
        echo
        if [ -n "$prev" ] && [ "$prev" != "$GITHUB_SHA" ]; then
            echo "### Changes since the previous development build"
            echo
            gh api "repos/$GH_REPO/compare/$prev...$GITHUB_SHA" \
                --jq '.commits[] | "- \(.commit.message | split("\n")[0]) (\(.sha[0:7]))"' || true
            echo
        fi
        checksums
    } > notes.md
    # recreated rather than edited, so it moves to this commit and to the top of the list
    gh release delete dev --cleanup-tag --yes 2>/dev/null || true
    gh release create dev "${files[@]}" --prerelease --target "$GITHUB_SHA" \
        --title "Development build ($short)" --notes-file notes.md
    echo "Published https://github.com/$GH_REPO/releases/tag/dev"
    exit 0
fi

if gh release view "$VERSION" >/dev/null 2>&1; then
    # a re-run for the same version: refresh the files only
    gh release upload "$VERSION" "${files[@]}" --clobber
    echo "Updated the files of $VERSION"
    exit 0
fi
case "$VERSION" in
    *-*) channel=--prerelease ;;
    *) channel=--latest ;;
esac
{
    about
    echo
    checksums
} > notes.md
gh release create "$VERSION" "${files[@]}" "$channel" --target "$GITHUB_SHA" \
    --title "SwitchRecomp $VERSION" --notes-file notes.md --generate-notes
url="https://github.com/$GH_REPO/releases/tag/$VERSION"
echo "Published $url"

if [ -n "${DISCORD_WEBHOOK:-}" ]; then
    jq -n --arg content "SwitchRecomp $VERSION is out: $url" '{content: $content}' |
        curl -fsS -H 'Content-Type: application/json' -d @- "$DISCORD_WEBHOOK" >/dev/null &&
        echo "Announced on Discord" || echo "::warning::The Discord announcement failed"
fi
